package pe.ganadoconecta.modulos.reproduccion.adaptadores.salida;import java.security.MessageDigest;import java.sql.Date;import java.time.*;import java.util.*;import org.springframework.dao.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.support.TransactionSynchronizationManager;import pe.ganadoconecta.modulos.ganado.aplicacion.AnimalNoEncontradoException;import pe.ganadoconecta.modulos.reproduccion.aplicacion.*;import pe.ganadoconecta.modulos.reproduccion.dominio.*;
public final class RepositorioPartosPostgres implements RepositorioPartos{private final JdbcTemplate jdbc;public RepositorioPartosPostgres(JdbcTemplate j){jdbc=j;}@Override public ResultadoRegistroParto registrar(Parto p,UUID op,byte[]h,int schema){if(!TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("Se requiere transacción");try{validar(p);int n=jdbc.update("INSERT INTO reproduccion.operacion_parto(operacion_id,ganaderia_id,parto_id,actor_usuario_id,schema_version,huella_sha256,confirmado_en) VALUES(?,?,?,?,?,?,?) ON CONFLICT(operacion_id) DO NOTHING",op,p.ganaderiaId(),p.id(),p.creadoPor(),schema,h,OffsetDateTime.ofInstant(p.creadoEn(),ZoneOffset.UTC));if(n==0)return reprocesar(p,op,h);jdbc.update("INSERT INTO reproduccion.parto(id,ganaderia_id,madre_id,padre_id,fecha_parto,resultado,observaciones,creado_por,creado_en) VALUES(?,?,?,?,?,?,?,?,?)",p.id(),p.ganaderiaId(),p.madreId(),p.padreId(),Date.valueOf(p.fecha()),p.resultado().name(),p.observaciones(),p.creadoPor(),OffsetDateTime.ofInstant(p.creadoEn(),ZoneOffset.UTC));for(UUID c:p.criaIds())jdbc.update("INSERT INTO reproduccion.parto_cria(parto_id,ganaderia_id,cria_id) VALUES(?,?,?)",p.id(),p.ganaderiaId(),c);return new ResultadoRegistroParto(op,p.id(),ResultadoRegistroParto.Estado.APLICADO,p.creadoEn());}catch(AnimalNoEncontradoException|DatoReproductivoInvalidoException|ConflictoReproductivoException x){throw x;}catch(DuplicateKeyException x){throw new ConflictoReproductivoException();}catch(DataAccessException x){throw new PersistenciaReproductivaException(x);}}
 private void validar(Parto p){String madre=sexo(p.ganaderiaId(),p.madreId());if(madre==null)throw new AnimalNoEncontradoException();if(!"HEMBRA".equals(madre))throw new DatoReproductivoInvalidoException("madreId");if(p.padreId()!=null&&!"MACHO".equals(sexo(p.ganaderiaId(),p.padreId())))throw new DatoReproductivoInvalidoException("padreId");for(UUID c:p.criaIds())if(sexo(p.ganaderiaId(),c)==null)throw new DatoReproductivoInvalidoException("criaIds");}
 private String sexo(UUID g,UUID a){List<String>x=jdbc.query("SELECT sexo FROM ganado.animal WHERE ganaderia_id=? AND id=?",(r,n)->r.getString(1),g,a);return x.isEmpty()?null:x.getFirst();}
 private ResultadoRegistroParto reprocesar(Parto p,UUID op,byte[]h){List<G>x=jdbc.query("SELECT ganaderia_id,parto_id,actor_usuario_id,huella_sha256,confirmado_en FROM reproduccion.operacion_parto WHERE operacion_id=? FOR UPDATE",(r,n)->new G(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getObject(3,UUID.class),r.getBytes(4),r.getObject(5,OffsetDateTime.class)),op);if(x.size()!=1||!x.getFirst().coincide(p,h))throw new ConflictoReproductivoException();return new ResultadoRegistroParto(op,p.id(),ResultadoRegistroParto.Estado.REPROCESADO,x.getFirst().fecha.toInstant());}
 @Override public List<Parto> listar(UUID g,UUID madre){if(sexo(g,madre)==null)throw new AnimalNoEncontradoException();try{return jdbc.query("SELECT p.id,p.ganaderia_id,p.madre_id,p.padre_id,p.fecha_parto,p.resultado,p.observaciones,p.creado_por,p.creado_en,COALESCE(array_agg(pc.cria_id ORDER BY pc.cria_id) FILTER(WHERE pc.cria_id IS NOT NULL),ARRAY[]::uuid[]) crias FROM reproduccion.parto p LEFT JOIN reproduccion.parto_cria pc ON pc.parto_id=p.id WHERE p.ganaderia_id=? AND p.madre_id=? GROUP BY p.id ORDER BY p.fecha_parto DESC,p.creado_en DESC,p.id",(r,n)->new Parto(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getObject(3,UUID.class),r.getObject(4,UUID.class),r.getDate(5).toLocalDate(),ResultadoParto.valueOf(r.getString(6)),r.getString(7),Arrays.asList((UUID[])r.getArray(10).getArray()),r.getObject(8,UUID.class),r.getObject(9,OffsetDateTime.class).toInstant()),g,madre);}catch(DataAccessException x){throw new PersistenciaReproductivaException(x);}}
 private record G(UUID ganaderia,UUID parto,UUID actor,byte[]huella,OffsetDateTime fecha){boolean coincide(Parto p,byte[]h){return ganaderia.equals(p.ganaderiaId())&&parto.equals(p.id())&&actor.equals(p.creadoPor())&&MessageDigest.isEqual(huella,h);}}
}
